arguments.file_text:
.change-password-panel .card {
    max-width: 400px;
}

@using sv_deb45fb53e0749ec9375376d2a9e8aa8.Models

@if (IsVisible && Session is not null)
{
    <div class="modal-backdrop show"></div>
    <div class="modal d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="OnCancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    <ul class="list-unstyled mb-0">
                        <li><strong>Device:</strong> @Session.Device</li>
                        <li><strong>Location:</strong> @Session.Location</li>
                        <li><strong>Last Active:</strong> @Session.LastActive.ToString("g")</li>
                    </ul>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="OnCancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="OnConfirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }
}

@using sv_deb45fb53e0749ec9375376d2a9e8aa8.Models
@inject ISettingsService SettingsService

<div class="security-section">
    @if (isLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (settings is not null)
    {
        <h4>Security Settings</h4>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <hr />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch"
                           id="twoFactor" checked="@settings.TwoFactorEnabled" disabled />
                </div>
            </div>
        </div>

        @if (settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted small">
                Last password change: @settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
            </p>
        }

        <h5 class="mt-4">Active Sessions</h5>
        @if (settings.Sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-striped">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != settings.Sessions[0])
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }

        <SessionRevokeDialog IsVisible="@(sessionToRevoke is not null)"
                             Session="sessionToRevoke"
                             OnConfirm="ConfirmRevokeAsync"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private SecuritySettings? settings;
    private bool isLoading = true;
    private ActiveSession? sessionToRevoke;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        settings = await SettingsService.GetSecuritySettingsAsync();
        isLoading = false;
    }

    private async Task HandleChangePasswordAsync((string current, string newPwd) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPwd);
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;

    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            settings = await SettingsService.GetSecuritySettingsAsync();
            statusMessage = "Session revoked successfully.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        finally
        {
            sessionToRevoke = null;
        }
    }
}

