@using sv_deb45fb53e0749ec9375376d2a9e8aa8.Models
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (isLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4>Appearance Settings</h4>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="card mb-3">
            <div class="card-body">
                <h6 class="card-title">Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{theme}")" value="@theme"
                               checked="@(selectedTheme == theme)"
                               @onchange="() => selectedTheme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-body">
                <h6 class="card-title">Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"size-{size}")" value="@size"
                               checked="@(selectedFontSize == size)"
                               @onchange="() => selectedFontSize = size" />
                        <label class="form-check-label" for="@($"size-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="language">Language</label>
            <select id="language" class="form-select" style="max-width:300px;"
                    @bind="selectedLanguage">
                @foreach (var lang in Languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="form-check form-switch mb-4">
            <input class="form-check-input" type="checkbox" role="switch"
                   id="compactMode" @bind="compactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>

        <div class="card mb-4">
            <div class="card-header">
                <h6 class="mb-0">Live Preview</h6>
            </div>
            <div class="card-body preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                <h5>Sample Heading</h5>
                <p class="@(compactMode ? "mb-1" : "mb-3")">
                    This is a preview of your selected appearance settings.
                    The theme is <strong>@selectedTheme</strong>, the font size is
                    <strong>@selectedFontSize</strong>, and the language is
                    <strong>@selectedLanguage</strong>.
                </p>
                <div class="d-flex gap-2 @(compactMode ? "flex-wrap" : "")">
                    <button class="btn btn-sm btn-primary">Primary</button>
                    <button class="btn btn-sm btn-secondary">Secondary</button>
                    <button class="btn btn-sm btn-outline-dark">Outline</button>
                </div>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private bool isLoading = true;
    private bool isSaving;
    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private string? statusMessage;
    private bool isError;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private string PreviewThemeClass => selectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontStyle => selectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var appearance = await SettingsService.GetAppearanceAsync();
        selectedTheme = appearance.Theme;
        selectedFontSize = appearance.FontSize;
        selectedLanguage = appearance.Language;
        compactMode = appearance.CompactMode;
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save settings: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

.appearance-section {
    max-width: 600px;
}

.preview-area {
    border-radius: 0.375rem;
    padding: 1.25rem;
    transition: background-color 0.3s, color 0.3s;
}

.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-dark {
    background-color: #212529;
    color: #f8f9fa;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #212529 50%);
    color: #495057;
}

